mapper.sql:
FROM t_attendance_record a
LEFT JOIN t_employee e ON e.id = a.employee_id AND e.is_deleted = 0
LEFT JOIN t_department d ON d.id = e.dept_id AND d.is_deleted = 0
WHERE a.is_deleted = 0

    AND a.employee_id = #{query.employeeId}


    AND a.attendance_date >= #{query.startDate}


    AND a.attendance_date <= #{query.endDate}

mapper.select:
SELECT


ORDER BY a.attendance_date DESC, a.id DESC
LIMIT #{offset}, #{size}
